"""Generate form data without modifying the generated base Pokédex."""
import json
from pathlib import Path
from pokemon_stats import convert

ROOT = Path(__file__).resolve().parent.parent


def main():
    forms = json.loads((ROOT / 'tools/forms.json').read_text(encoding='utf-8'))
    for form in forms:
        form['stats'] = convert(form['baseStats'])
        form['stats']['bst'] = sum(form['baseStats'].values())
    (ROOT / 'js/data/forms.js').write_text(
        '/* Generated by tools/generate_forms.py from tools/forms.json. */\n'
        + 'G.FORM_DEFS = ' + json.dumps(forms, ensure_ascii=False, indent=2) + ';\n', encoding='utf-8')


if __name__ == '__main__':
    main()
